		status: seed.status,
		outcome: seed.outcome ?? null,
		parent: seed.parent ?? null,
		milestone: seed.milestone,
		worktree: seed.worktree ?? null,
		commit: seed.commit ?? null,
		createdAt: now - seed.created * MIN,
		updatedAt: now - seed.updated * MIN,
		...seed.priority !== void 0 ? { priority: seed.priority } : {},
		paused: seed.paused ? {
			at: now - seed.paused.ago * MIN,
			by: seed.paused.by
		} : null,
		cancel: seed.cancel ? {
			at: now - seed.cancel.ago * MIN,
			by: seed.cancel.by,
			reason: seed.cancel.reason,
			branch: seed.cancel.branch
		} : null,
		handovers: (seed.handovers ?? []).map(({ ago, ...h }) => ({
			...h,
			at: now - ago * MIN
		})),
		planTask: seed.planTask ?? null,
		cites: seed.cites ?? []
